<script>import{t}from'../logic/i18n.js';import{getAllSlugs}from'../logic/wiki.js';let{lang='fa',isOpen=false,isMobile=false,currentSlug='home',onNavigate,onToggle}=$props();const pages=$derived(getAllSlugs());const isLtr=$derived(lang==='en');let noT=$state(false);$effect(()=>{const _=isLtr;if(!isOpen){noT=true;requestAnimationFrame(()=>requestAnimationFrame(()=>noT=false))}});</script>{#if isMobile}<div class="so" class:so--o={isOpen} role="button" tabindex="-1" onclick={()=>onToggle&&onToggle()} onkeydown={(e)=>{if(e.key==='Escape'||e.key==='Enter')onToggle&&onToggle()}}></div><aside class="sb sb--m" class:sb--o={isOpen} class:sb--ltr={isLtr} class:sb--no-t={noT}><div class="sh"><span class="st2">{t(lang,'allPages')}</span><button class="sc" onclick={()=>onToggle&&onToggle()} aria-label={t(lang,'closeSidebar')}><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="20" height="20"><path d="M18 6 6 18M6 6l12 12"/></svg></button></div><nav class="sn">{@render pagesList()}</nav></aside>{/if}{#if !isMobile}<div class="sw"><aside class="sb sb--d" class:sb--do={isOpen} class:sb--ltr={isLtr}><div class="sh"><span class="st2">{t(lang,'allPages')}</span></div><nav class="sn">{@render pagesList()}</nav></aside><div class="st" class:st--ltr={isLtr} role="button" tabindex="0" onclick={()=>onToggle&&onToggle()} onkeydown={(e)=>{if(e.key==='Enter'||e.key===' ')onToggle&&onToggle()}}><svg class="st-arr" class:st-arr--o={isOpen} viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="16" height="16"><path d="M9 18l6-6-6-6"/></svg><span class="tl">{t(lang,'allPages')}</span></div></div>{/if}{#snippet pagesList()}<ul class="pl">{#each pages as page(page.slug)}<li><button class="pli" class:pli--a={currentSlug===page.slug} onclick={()=>{if(onNavigate)onNavigate(page.slug);if(isMobile&&onToggle)onToggle()}}><svg class="pi" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg><span class="pt">{page.titles[lang]||page.titles.fa||page.slug}</span></button></li>{/each}</ul>{/snippet}<style>.so{position:fixed;inset:0;background:rgba(0,0,0,0.4);z-index:90;opacity:0;pointer-events:none;transition:opacity var(--transition-normal)}.so--o{opacity:1;pointer-events:auto}.sb--m{position:fixed;top:0;bottom:0;right:0;width:var(--sidebar-width);max-width:85vw;background:var(--color-bg-primary);z-index:95;display:flex;flex-direction:column;box-shadow:var(--shadow-lg);transform:translateX(100%);pointer-events:none;transition:transform var(--transition-normal)}.sb--m.sb--o{transform:translateX(0);pointer-events:auto}.sb--m.sb--ltr{right:auto;left:0;border-left:none;border-right:1px solid var(--color-border);transform:translateX(-100%)}.sb--m.sb--ltr.sb--o{transform:translateX(0)}.sb--m:not(.sb--ltr){border-left:1px solid var(--color-border)}.sb--no-t{transition:none!important}.sw{position:sticky;top:var(--header-height);height:calc(100vh - var(--header-height));display:flex;flex-shrink:0;z-index:10}.sb--d{width:0;overflow:hidden;background:var(--color-bg-primary);display:flex;flex-direction:column;transition:width var(--transition-normal)}.sb--do{width:var(--sidebar-width)}.st{width:32px;flex-shrink:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:0.3rem;cursor:pointer;background:var(--color-bg-primary);color:var(--color-text-muted);transition:background var(--transition-fast),color var(--transition-fast)}.st:hover{background:var(--color-bg-hover);color:var(--color-accent)}.st:not(.st--ltr){border-left:1px solid var(--color-border)}.st--ltr{border-right:1px solid var(--color-border)}.st--ltr .st-arr{transform:scaleX(-1)}.st-arr{transition:transform var(--transition-normal)}.st-arr--o{transform:rotate(180deg)}.st--ltr .st-arr--o{transform:scaleX(-1) rotate(180deg)}.tl{writing-mode:vertical-rl;font-size:var(--font-size-xs);font-weight:600;letter-spacing:0.05em;text-transform:uppercase}.sh{display:flex;align-items:center;justify-content:space-between;padding:1rem;border-bottom:1px solid var(--color-border);flex-shrink:0}.st2{font-weight:600;font-size:var(--font-size-sm);color:var(--color-text-secondary);text-transform:uppercase;letter-spacing:0.05em}.sc{display:flex;align-items:center;justify-content:center;background:none;border:none;color:var(--color-text-muted);cursor:pointer;padding:4px;border-radius:var(--radius-sm)}.sc:hover{color:var(--color-text-primary);background:var(--color-bg-hover)}.sn{flex:1;overflow-y:auto;padding:0.5rem 0}.pl{list-style:none;padding:0;margin:0}.pli{display:flex;align-items:center;gap:0.75rem;width:100%;padding:0.6rem 1rem;border:none;background:none;color:var(--color-text-secondary);font-family:var(--font-body);font-size:var(--font-size-sm);cursor:pointer;text-align:right;transition:all var(--transition-fast);white-space:nowrap}.pli:hover{background:var(--color-bg-hover);color:var(--color-text-primary)}.pli--a{background:var(--color-accent-bg);color:var(--color-accent);font-weight:600;border-left:3px solid var(--color-accent)}.pi{width:18px;height:18px;flex-shrink:0}.pt{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}</style>